import{c as t,Q as a,j as o,m as n}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"How to Build an AI GTM Brain using Claude Code","description":"","frontmatter":{},"headers":[],"relativePath":"research/tweets/2026-06-09-@nifinet-440907.md","filePath":"research/tweets/2026-06-09-@nifinet-440907.md","lastUpdated":1785909234000}'),r={name:"research/tweets/2026-06-09-@nifinet-440907.md"};function i(s,e,h,l,d,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="how-to-build-an-ai-gtm-brain-using-claude-code" tabindex="-1">How to Build an AI GTM Brain using Claude Code <a class="header-anchor" href="#how-to-build-an-ai-gtm-brain-using-claude-code" aria-label="Permalink to &quot;How to Build an AI GTM Brain using Claude Code&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/nifinet/status/2064397495036440907" target="_blank" rel="noreferrer">@nifinet</a>（Nicolas Finet）<br><strong>日期</strong>：2026-06-09<br><strong>類型</strong>：Twitter Article<br><strong>統計</strong>：❤️ 491 · 🔁 52 · 👁 57548 · 🔖 1426</p><hr><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>用 Claude Code 分六步驟構建 AI GTM Brain（Sense→Remember→Judge→Act→Learn + cron），以 $400/月 token 預算取代五名招募計畫，核心設計原則是 agent 吃 command line，介面與工具層隔離。</p><hr><h2 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h2><ol><li>GTM 的難點不在「多發」而在「判斷」—— 哪個帳號、為何此刻、說什麼</li><li>五層架構：Sense（市場信號）→ Remember（帳號記憶）→ Judge（值不值得聯繫）→ Act（觸發型開場）→ Learn（回饋改善）</li><li>核心設計原則：agent 吃 command line；介面層隔離（stub adapter → 換工具只改一層）</li><li>作者實際部署：Sortlist 場景，$400/月 token，取消五個人力招募</li><li>每步附 Claude Code prompt，可直接複製構建</li></ol><hr><h2 id="關鍵數據-工具-引用" tabindex="-1">關鍵數據 / 工具 / 引用 <a class="header-anchor" href="#關鍵數據-工具-引用" aria-label="Permalink to &quot;關鍵數據 / 工具 / 引用&quot;">​</a></h2><ul><li>部署成本：$400/月 token（Sortlist）</li><li>取消：五名預定招募人力</li><li>工具：Claude Code（command line）</li><li>Adapter 範例：apollo_search、instantly_send（隔離不硬編碼）</li><li>觸發：cron 定時執行</li></ul><hr><h2 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h2><ol><li>文章偏 high-level，具體 Claude Code prompt 以圖片呈現（<code>[]</code> placeholder），需 comment BRAIN 才能取得完整素材</li><li>$400/月節省五人力的 ROI 說法缺乏成本對比基準（五人薪資 vs 工具費用）</li><li>適用於有清晰 ICP 信號的 B2B outbound，非通用 GTM 方案</li></ol><hr><h2 id="_5-維度評分" tabindex="-1">5 維度評分 <a class="header-anchor" href="#_5-維度評分" aria-label="Permalink to &quot;5 維度評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>7</td><td>六步驟有結構但 prompt 藏在回覆中</td></tr><tr><td>B. 創新性 (20%)</td><td>7</td><td>GTM Agent 非新概念，command-line-first 設計有洞見</td></tr><tr><td>C. 證據品質 (20%)</td><td>6</td><td>真實部署數據（$400/月）但缺詳細驗證</td></tr><tr><td>D. 技術深度 (15%)</td><td>6</td><td>架構清楚，程式碼 stub 未完整展示</td></tr><tr><td>E. 泛化性 (15%)</td><td>7</td><td>B2B outbound 場景明確，可遷移</td></tr></tbody></table><p><strong>加權總分：6.65 → Agent</strong></p><hr><h2 id="整合決策" tabindex="-1">整合決策 <a class="header-anchor" href="#整合決策" aria-label="Permalink to &quot;整合決策&quot;">​</a></h2><p><strong>Agent</strong> — 多步驟自主流程（Sense→Judge→Act 閉環 + cron 排程）</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>When a team says they want AI for growth, they usually mean a faster send. An agent that fires the same template at a longer list, day and night.</p><p>That is the cheap half of the job, and it stopped working a while ago. The hard half is the judgment around the send: which company to contact, why this week, and what to say that proves you noticed them. A bigger list does nothing for that.</p><p>A GTM brain is the system that makes that call for you, every day, without you in the loop. It has five parts, and they run as one loop:</p><ul><li><p>Sense. Watch the market for the accounts that just moved.</p></li><li><p>Remember. Keep everything you learn about each one.</p></li><li><p>Judge. Decide who is worth a message, and why now.</p></li><li><p>Act. Write the opener from the real trigger.</p></li><li><p>Learn. Track what comes back, and improve next week.</p></li></ul><p>Get those five right and sending becomes the easy part.</p><p>One idea sits under the whole build: people get a UX, software gets an API, an agent gets a command line. You run this one from the command line on a schedule, and the six steps below build it, each with the prompt I paste into Claude Code.</p><p>[]</p><h2 id="step-1-the-contract" tabindex="-1">Step 1. The contract <a class="header-anchor" href="#step-1-the-contract" aria-label="Permalink to &quot;Step 1. The contract&quot;">​</a></h2><p>Write the boundary first, before any agent code.</p><p>This is the piece that saves you the day you swap tools. Your code should never hardcode the name of your intent vendor or your email tool. It needs two shapes and nothing else: a signal coming in, and a message going out. Open Claude Code in an empty folder and give it this:</p><p>[]</p><p>What good looks like. Two small files you can read in a minute, and a loop that runs end to end on fake data. You see a signal go in and a draft come out before you pay for a single integration.</p><p>Where it breaks. The shortcut that bites you is letting the code call apollo_search or instantly_send directly. Do that and every part is welded to one vendor, so a tool swap means rewriting all five. Keep the two shapes in front and a swap costs one new adapter.</p><p>[]</p><h2 id="step-2-sense-the-market" tabindex="-1">Step 2. Sense the market <a class="header-anchor" href="#step-2-sense-the-market" aria-label="Permalink to &quot;Step 2. Sense the market&quot;">​</a></h2><p>Start from movement. Something changed at a company, and that change is the reason to reach out.</p><p>Four kinds of movement carry the weight. Ten years on the marketplace taught me to watch these and let the rest go:</p><ul><li><p>Job. A role opens, gets reposted, or someone lands in a budget-owning seat.</p></li><li><p>Social. A company engages a competitor, or posts about the problem you solve.</p></li><li><p>Company. A launch, an expansion, a change in the stack.</p></li><li><p>Funding. A round or acquisition that drops fresh budget with a mandate.</p></li></ul><p>Most teams watch one of these and ignore the rest. Inside Sortlist the coverage comes from Signals, our own intent tool, but the principle holds whether you buy it or scrape it yourself.</p><p>This part is small. Build it in one pass:</p><p>[]</p><p>What good looks like. A run that prints &quot;sensed 11 signals across 7 accounts,&quot; with the company that has both a funding round and a new role landing as one hot, clustered account.</p><p>Where it breaks. Sensing everything and ranking nothing. Dump raw signals downstream and you end up treating a lone like from a tourist the same as a funding round at a perfect-fit account. Cluster at the door instead of pushing the mess onto the judge.</p><p>[]</p><h2 id="step-3-remember-every-account" tabindex="-1">Step 3. Remember every account <a class="header-anchor" href="#step-3-remember-every-account" aria-label="Permalink to &quot;Step 3. Remember every account&quot;">​</a></h2><p>This is the piece most tools skip, and it is why they end up as a mail merge with a prompt on top.</p><p>Keep one record per company: every signal you saw, every message you sent, every reply, every outcome. A third funding round means something completely different once you know you already emailed them twice and got silence. Without that history, you treat a warm account exactly like a cold one.</p><p>This is the part to get right, so spec it fully:</p><p>[]</p><p>What good looks like. You ask the store for any account and get its whole story back in one call: what moved, what you sent, what came back. It never reaches out twice the same way.</p><p>Where it breaks. Most teams skip this and ship without it. Then they judge the system on its cold-start output, decide it is generic, and switch it off in week three, one week before the history would have made it sharp. Build this part first. The other four lean on it.</p><p>[]</p><h2 id="step-4-judge-who-and-why-now" tabindex="-1">Step 4. Judge who and why now <a class="header-anchor" href="#step-4-judge-who-and-why-now" aria-label="Permalink to &quot;Step 4. Judge who and why now&quot;">​</a></h2><p>This is where Claude does the work, and where the system stops being a script.</p><p>The judge reads the new signal, pulls the account&#39;s full history from memory, takes in your definition of a good customer, and decides three things:</p><ul><li><p>is this account worth a message right now,</p></li><li><p>why,</p></li><li><p>and which play to run.</p></li></ul><p>This is the part a competitor cannot copy, which is why it is worth building yourself.</p><p>The prompt names the model, the temperature, the fallback, and where the system prompt lives:</p><p>[]</p><p>What good looks like. The hot account scores high with a why_now you could paste straight into the email. The lukewarm ones come back as skip, with a reason. A system that says no to three accounts in four beats one that mails all four.</p><p>Where it breaks. Scoring a signal without the memory. On its own, a fresh signal cannot tell an account you have chased twice from one you have never touched, so the model repeats the same opener and you read as a stalker. Without the history, the score is just a guess.</p><p>[]</p><h2 id="step-5-act-on-the-trigger" tabindex="-1">Step 5. Act on the trigger <a class="header-anchor" href="#step-5-act-on-the-trigger" aria-label="Permalink to &quot;Step 5. Act on the trigger&quot;">​</a></h2><p>It writes only after the judge has decided who and why.</p><p>The rule for this part is simple: quote the trigger back. &quot;Saw you opened a Head of RevOps role, second ops hire this quarter.&quot; Never &quot;Hi &quot;. If the message could have gone out unchanged last month, you skipped the trigger.</p><p>Build this part the same way, with delivery defaulting to a dry run:</p><p>[]</p><p>What good looks like. A draft you would forward as is, opening on something true about the account this week. Run it in dry-run and read ten in a row before one ever leaves the building.</p><p>Where it breaks. Wiring delivery live before you have read the output. A system that sends on its own will mail one confident, wrong opener to your whole list before a human sees it. Keep dry-run the default; make --live a decision.</p><p>[]</p><h2 id="step-6-learn-from-what-comes-back" tabindex="-1">Step 6. Learn from what comes back <a class="header-anchor" href="#step-6-learn-from-what-comes-back" aria-label="Permalink to &quot;Step 6. Learn from what comes back&quot;">​</a></h2><p>An agent that never learns is just a faster script. This last part is what keeps it from staying one.</p><p>Feed every outcome back into memory and let it grade its own plays. Signals that keep booking meetings get more weight. Copy that keeps failing gets cut. Test, score, keep or kill. This is why it gets better week over week, without you tuning it by hand.</p><p>This part is small too:</p><p>[]</p><p>Then wire the five parts into one command:</p><p>[]</p><p>Now a single line of cron runs the whole thing daily. If you already run a fleet on an agent runtime, drop it in there as a skill instead.</p><p>[]</p><p>What good looks like. Month one, it weights the buckets the way you guessed. Month three, it weights them the way your market actually behaves, and the shortlist is shorter, sharper, and ordered by what converts.</p><p>Where it breaks. Logging sends but never outcomes. With no result data the weights never move and you have bought an expensive scheduler. Wire the reply and meeting data back in from day one, by hand if you have to.</p><p>[]</p><h2 id="the-two-prompts" tabindex="-1">The two prompts <a class="header-anchor" href="#the-two-prompts" aria-label="Permalink to &quot;The two prompts&quot;">​</a></h2><p>Every prompt so far builds a part once, then you set it aside. These two are different: the system uses them on every account, every run. The judgment and the voice live here, so these are the ones to keep and tune.</p><p>The judge runs on this:</p><p>[]</p><p>And the drafting step runs on this:</p><p>[]</p><p>Both ship in the repo as editable files, and they are what you will tune most against your own market.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><p>With the five wired together, it runs on a schedule and does this on its own:</p><ul><li><p>sweeps the market,</p></li><li><p>scores the accounts that moved and drops the rest,</p></li><li><p>drafts the few worth a message,</p></li><li><p>posts a ranked shortlist to Slack, a reason next to each name.</p></li></ul><p>Two minutes: approve, edit, or kill. No list to build, no subject lines to guess, no Monday meeting about who to call.</p><p>I run a fleet on this shape across Sortlist for about $400 a month in tokens. We had five hires planned this year and cancelled them, because the work runs on the token budget now. The growth brain is the one I would build first. It pays for itself the first time it books a meeting you would have missed.</p><h2 id="start-with-two" tabindex="-1">Start with two <a class="header-anchor" href="#start-with-two" aria-label="Permalink to &quot;Start with two&quot;">​</a></h2><p>You do not need all five. Build memory first, then the judge on top of it.</p><p>Point them at the stub data, run it dry for a week to trust the loop, then wire in one real signal source. You will get a ranked list of accounts worth a message, each with the reason it made the cut, pulled from signals you were already ignoring. That is the part worth paying for.</p><p>I packaged a clean version of the whole thing: the five parts, both adapters, the config, the build prompt for every step, the two prompts above, and the cron to run it. A small skeleton you can clone and bend to your own market. Comment BRAIN and I will send it.</p>',101)])])}const m=t(r,[["render",i]]);export{c as __pageData,m as default};
